using System.Text.Json;
using System.Text.Json.Serialization.Metadata;

var options = new JsonSerializerOptions
{
    TypeInfoResolver = new DefaultJsonTypeInfoResolver()
};

// 1. Strongly-typed metadata retrieval: GetTypeInfo<T>()
JsonTypeInfo<Person> personInfo = (JsonTypeInfo<Person>)options.GetTypeInfo(typeof(Person));
Console.WriteLine($"Got typed metadata for: {personInfo.Type.Name}");

string json = JsonSerializer.Serialize(new Person("Alice", 30), personInfo);
Console.WriteLine($"Serialized: {json}");

Person deserialized = JsonSerializer.Deserialize(json, personInfo)!;
Console.WriteLine($"Deserialized: {deserialized}");

// 2. Probe without throwing: TryGetTypeInfo()
if (options.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? info))
{
    var typed = (JsonTypeInfo<Person>)info!;
    Console.WriteLine($"\nTryGetTypeInfo succeeded for Person: {typed.Type.Name}");
}

// Now try a type that has NO resolver coverage (use a bare options with no resolver)
var emptyOptions = new JsonSerializerOptions
{
    TypeInfoResolver = JsonTypeInfoResolver.Combine() // empty composite — resolves nothing
};

if (emptyOptions.TryGetTypeInfo(typeof(Person), out JsonTypeInfo? missing))
{
    Console.WriteLine("Unexpected: found metadata");
}
else
{
    Console.WriteLine("\nTryGetTypeInfo returned false for Person on empty resolver — no exception thrown.");
}

public record Person(string Name, int Age);

